import request from '../utils/request';

// 首页统计
export const getChartData = params => {
    return request({
        url: 'chart-data',
        method: 'get',
        params: params
    });
};

export const getOrgTypeStats = params => {
    return request({
        url: 'org-type-stats',
        method: 'get',
        params: params
    });
};

export const getOrgTypeStats2 = params => {
    return request({
        url: 'org-type-stats2',
        method: 'get',
        params: params
    });
};

export const getChartDataMonthly = params => {
    return request({
        url: 'chart-data-monthly',
        method: 'get',
        params: params
    });
};

export const getDetail = params => {
    return request({
        url: 'chart-data-detail1',
        method: 'get',
        params: params
    });
};

// 总览 
export const getDataAll = params => {
    return request({
        url: 'chart-data-all',
        method: 'get',
        params: params
    });
};
export const getDataMonthlyAll = params => {
    return request({
        url: 'chart-data-monthly-all',
        method: 'get',
        params: params
    });
};

// 导出
export const getExport = params => {
    return request({
        url: 'export-excel',
        method: 'get',
        params: params,
        responseType: 'blob'
    });
};

// 导出
export const getImport = params => {
    return request({
        url: 'import',
        method: 'post',
        data: params,
    });
};


// 模型列表  
export const getModelList = params => {
    return request({
        url: 'model-list',
        method: 'get',
        params: params
    });
};

// 机构列表  
export const getOrgList = params => {
    return request({
        url: 'org-list',
        method: 'get',
        params: params
    });
};

